 * ------------------------------------------------------------------- */
function sma_contactpoint_schema() {
    // Use the same phone number for regular calls and WhatsApp.
    $phone = '+91-XXXXXXXXXX'; // <-- replace with your actual number (include country code)
    $email = 'info@sanctify.in'; // <-- replace with your email
    $data = [
        '@context' => 'https://schema.org',
        '@type'    => 'ContactPoint',
        'telephone'        => $phone,
