/** -------------------------------------------------------------------
 * Phase 8: FAQPage schema – pulls from a custom post type "faq".
 * ------------------------------------------------------------------- */
function sma_faq_schema() {
    $faqs = get_posts([
        'post_type'      => 'faq',
        'posts_per_page' => -1,
        'post_status'    => 'publish',
    ]);
    if (empty($faqs)) {
        return;
    }
    $questions = [];
    foreach ($faqs as $faq) {
        $questions[] = [
            '@type'          => 'Question',
            'name'           => get_the_title($faq),
            'acceptedAnswer' => [
                '@type' => 'Answer',
                'text'  => wp_strip_all_tags(apply_filters('the_content', $faq->post_content)),
            ],
        ];
    }
    $data = [
        '@context' => 'https://schema.org',
        '@type'    => 'FAQPage',
        'mainEntity' => $questions,
    ];
    echo '<script type="application/ld+json">' . wp_json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '</script>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}
add_action('wp_head', 'sma_faq_schema');

/** -------------------------------------------------------------------
 * Phase 9: BreadcrumbList schema – for better navigation in SERPs.
 * ------------------------------------------------------------------- */
function sma_breadcrumb_schema() {
    if (!is_singular()) {
        return;
    }
    $post = get_queried_object();
    $crumbs = [];
    $crumbs[] = [
        '@type'    => 'ListItem',
        'position' => 1,
        'name'     => get_bloginfo('name'),
        'item'     => home_url('/')
    ];
    if (is_category() || is_tax()) {
        $term = get_queried_object();
        $crumbs[] = [
            '@type'    => 'ListItem',
            'position' => 2,
            'name'     => $term->name,
            'item'     => get_term_link($term)
        ];
    } else {
        $crumbs[] = [
            '@type'    => 'ListItem',
            'position' => 2,
            'name'     => $post->post_title,
            'item'     => get_permalink($post)
        ];
    }
    $data = [
        '@context' => 'https://schema.org',
        '@type'    => 'BreadcrumbList',
        'itemListElement' => $crumbs,
    ];
    echo '<script type="application/ld+json">' . wp_json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '</script>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}
add_action('wp_head', 'sma_breadcrumb_schema');

